UBOOT_MODULE_LIST = [
    "ASIA", "ASIAA", "ASIB", "ASIBA", "ASIAL", "FSMF", "FSIH", "FBBC", "FBIH", "ABIA", "ABIAL", "ABIC"
]
BIOS_MODULE_LIST = [
    "ASIL", "ABIO", "ABIN", "ASIK", "ABIL", "ASOE"
]
prepare_firmware = "{}/prepare-firmware.sh".format(__file__.rsplit("/", 1)[0])


def setup_connections(remote=False):
    """
    Setup connection for primary smod and secondary smod if exists and return connections list
    param hostname: lmp ip address
    return: list with setup connections
    """
    connection_list = []
    secondary_smod_ip = ''
    if remote:
        remote_connection = ssh.connect(hostname=robot_var("REMOTE_VM_IP"), username="ute")
    primary_smod = ssh.connect(hostname="192.168.255.129",
                               username="toor4nsn",
                               password="oZPS0POrRieRtu", proxy=None if not remote else remote_connection)
    connection_list.append(primary_smod)
    primary_smod_side = primary_smod.execute("hostname").rstrip()
    if primary_smod_side == "fct-0a":
        check_secondary_smod = r"""cat /etc/hosts | grep 'fct-4a' | awk '{print $3}'"""
        secondary_smod_ip = primary_smod.execute(check_secondary_smod).rstrip()
    elif primary_smod_side == "fct-4a":
        check_secondary_smod = r"""cat /etc/hosts | grep 'fct-0a' | awk '{print $3}'"""
        secondary_smod_ip = primary_smod.execute(check_secondary_smod).rstrip()
    if not secondary_smod_ip:
        check_secondary_smod = r"""netstat -rn | grep '192.168.255.7' | awk '{print $2}'"""
        secondary_smod_ip = primary_smod.execute(check_secondary_smod).rstrip()
    if secondary_smod_ip:
        secondary_smod = ssh.connect(hostname=secondary_smod_ip,
                                     username="toor4nsn",
                                     password="oZPS0POrRieRtu",
                                     proxy=primary_smod)
        connection_list.append(secondary_smod)
    return connection_list


@robot_kw
def get_bbmod_ips(connections):
    """
    Return bbmod ips from all connections
    For FSMF and FSIH returned is also FSPD/FSPM board
    param connections: list of setup connections
    """
    bb_dict = {}
    bb_list = []
    for conn in connections:
        for fsp in range(1, 10):
            check_fsp = r"""cat /etc/hosts | grep -w 'fsp-{0}a\|fsp{0}' | awk '{{print $1}}' | head -1""".format(fsp)
            fsp_ip = conn.execute(check_fsp).rstrip()
            if fsp_ip == '':
                continue
            ping_cmd = "timeout 1s ping -c 1 {} > /dev/null 2>&1; echo $?".format(fsp_ip)
            rc = conn.execute(ping_cmd)
            if rc.rstrip() == '0':
                bb_list.append(fsp_ip)
        bb_dict.update({conn: bb_list})
        bb_list = []
    robot_logger("BB IP dictionary: {}".format(bb_dict), "INFO", False)
    return bb_dict


@robot_kw
def update_uboot(module_type, conn, timeout=300):
    """
    Performing uboot and fpga firmware upgrade
    return True or False for reset testline
    param module_type: module type eg. ASIK, ABIA, FSMF etc
    param connection: object of setup smod connection
    """
    perform_reset = False
    check_version = conn.execute("/ffs/run/prepare-firmware.sh -v")
    set_robot_test_variable("INITIAL_UBOOT", get_uboot_version(conn))
    robot_logger("Check Uboot version {}".format(check_version), "INFO", False)
    downgrade_needed = "versions are different" in check_version
    if downgrade_needed:
        robot_logger("[{}][{}] Performing Uboot Downgrade".format(module_type,
                                                                  conn.params['hostname']), "INFO")
        uboot_output = conn.execute("/ffs/run/prepare-firmware.sh", timeout)
        robot_logger("Uboot output \n{}".format(uboot_output), "INFO", False)
        uboot_recheck = conn.execute("/ffs/run/prepare-firmware.sh -v", timeout)
        robot_logger("Uboot recheck \n{}".format(uboot_recheck), "INFO", False)
        if "u-boot versions are the same" in uboot_recheck:
            perform_reset = True
            if "FPGA versions are different" in check_version:
                robot_logger("[{}][{}] Performing FPGA Reconfig".format(module_type,
                                                                        conn.params['hostname']), "INFO")
                conn.send_command("fsm_fpga_upgrade -reconfig")
                reconnect(conn)
                perform_reset = False
        else:
            robot_logger("[{}][{}] Uboot Downgrade Unsuccessfull.".format(module_type,
                                                                          conn.params['hostname']), "WARN")
    else:
        robot_logger("[{}][{}] Uboot Downgrade not needed!".format(module_type,
                                                                   conn.params['hostname']), "info")
    return perform_reset


@robot_kw
def update_bios(module_type, conn, timeout=300):
    """
    Performing bios and fpga firmware upgrade
    return True or False for reset testline
    param module_type: module type eg. ASIK, ABIA, FSMF etc
    param connection: object of setup smod connection
    """
    perform_reset = False
    module_bios_file = {
        "ABIO": "ASP-SNFB1-MC-BW",
        "ABIN": "ASP-SNFB1-MC-BW",
        "ABIL": "ASPA-MC-BW",
        "ASIL": "FCT-SNFB1-MC-BW",
        "ASIK": "FCT-MC-BW",
        "ASOE": "ASC-SNFB1-MC-BW"
    }
    module_fpga_file = {
        "ASIK": "FCT-PC",
        "ASOE": "ASC-PCO8-BW"
    }
    if str(conn.execute("test -f /tmp/startup_HWAPI.log.xz; echo $?").rstrip()) == '0':
        cat_cmd = "xzcat /tmp/startup_HWAPI.log.xz"
    else:
        cat_cmd = "cat /tmp/startup_HWAPI.log"
    binary_bios_version = conn.execute("{} | grep 'running bios version' | awk '{{print $12}}'".format(cat_cmd)).rstrip()
    running_bios_version = conn.execute("{} | grep 'running bios version' | awk '{{print $9}}'".
                                        format(cat_cmd)).replace(",", "").rstrip()
    cpu_type = conn.execute("cat /proc/cpuinfo | grep ste | head -n 1 | awk -F ' ' '{print $3}'").rstrip()
    robot_logger("[{}][{}] Running Bios Version {} Binary Bios Version {}".format(
        module_type,
        conn.params['hostname'],
        running_bios_version, binary_bios_version), "info")
    downgrade_supported = True if cpu_type in ('3', '5', '7') else False
    downgrade_needed = running_bios_version not in binary_bios_version
    if downgrade_needed and downgrade_supported:
        bios_file_name_path = conn.execute("find /ffs/run/swpool/LFS -iname {}*.bin".
                                           format(module_bios_file[module_type])).rstrip()
        bios_output = conn.execute(f"update_bios.sh -F {'-d' if module_type in ['ABIL'] else '-D'} "
                                   f"{bios_file_name_path}", timeout=timeout)
        robot_logger("[{}][{}] BIOS Downgraded\n{}.".format(module_type,
                                                            conn.params['hostname'],
                                                            bios_output), "INFO", False)
        if "Successfully updated bios on bootflash" in bios_output:
            perform_reset = True
        else:
            robot_logger("[{}][{}] BIOS Downgrade Unsuccessfull.".format(module_type,
                                                                         conn.params['hostname']), "WARN")
    else:
        robot_logger("[{}][{}] BIOS Downgrade not needed!".format(module_type,
                                                                  conn.params['hostname']), "info")
    if module_type in module_fpga_file.keys():
        fpga_file = module_fpga_file[module_type]
        fpga_file_name_path = conn.execute("find /ffs/run/swpool/LFS -iname {}*.bin".format(fpga_file)).rstrip()
        check_fpga_upgrade = conn.execute("fsm_fpga_upgrade -c {}".format(fpga_file_name_path)).rstrip()
        if "upgrade needed" in check_fpga_upgrade:
            robot_logger("[{}][{}] Performing FPGA Downgrade".format(module_type,
                                                                     conn.params['hostname']), "INFO")
            fpga_output = conn.execute("fsm_fpga_upgrade -f {}".format(fpga_file_name_path), timeout)
            if "upgrade was successful" in fpga_output:
                conn.send_command("fsm_fpga_upgrade -reconfig")
                reconnect(conn)
                perform_reset = False
            else:
                robot_logger("[{}][{}] FPGA Downgrade Unsuccessfull.".format(module_type,
                                                                             conn.params['hostname']), "WARN")
        else:
            robot_logger("[{}][{}] FPGA Downgrade not needed!".format(module_type,
                                                                      conn.params['hostname']), "info")
    return perform_reset


@robot_kw
def downgrade_uboot(remote=False):
    """
    Downgrading uboot/bios firmware for specific modules
    return True or False for reset testline
    """
    perform_reset = False
    check_module_type = r"""sysinfo 2>&1| head -n10 | grep "ID_00_MODULE_ID_\[0\]" | awk -F "'" '{print $2}'"""
    connection_list = setup_connections(remote)
    bb_dict = get_bbmod_ips(connection_list)
    for sm_conn in reversed(connection_list):
        try:
            sm_conn.files.put(prepare_firmware, "/ffs/run/prepare-firmware.sh")
            sm_conn.execute("chmod +x /ffs/run/prepare-firmware.sh")
        except Exception as e:
            robot_logger("Copying prepare-firmware.sh failed due to: {}".format(e), "ERROR")
            return
        finally:
            sm_conn.files.close()
        for bb_ip in reversed(bb_dict[sm_conn]):
            try:
                bb_conn = ssh.connect(hostname=bb_ip,
                                      username="toor4nsn",
                                      password="oZPS0POrRieRtu",
                                      proxy=sm_conn)
                bb_type = bb_conn.execute(check_module_type).rstrip()
                if bb_type in UBOOT_MODULE_LIST:
                    perform_reset = True if update_uboot(bb_type, bb_conn) else perform_reset
                elif bb_type in BIOS_MODULE_LIST:
                    perform_reset = True if update_bios(bb_type, bb_conn) else perform_reset
            except Exception as e:
                robot_logger("Downgrade failed due to - {}".format(e), "ERROR")
            finally:
                bb_conn.disconnect()
        sm_type = sm_conn.execute(check_module_type).rstrip()
        try:
            if sm_type in UBOOT_MODULE_LIST:
                perform_reset = True if update_uboot(sm_type, sm_conn) else perform_reset
            elif sm_type in BIOS_MODULE_LIST:
                perform_reset = True if update_bios(sm_type, sm_conn) else perform_reset
        except Exception as e:
            robot_logger("Downgrade failed due to - {}".format(e), "ERROR")
            raise UbootDowngradeError("Downgrade failed due to - {}".format(e))
        finally:
            sm_conn.execute("rm /ffs/run/prepare-firmware.sh")
            sm_conn.disconnect()
    return perform_reset


def reconnect(conn):
    attempt = 0
    robot_logger("[{}] Disconnecting...".format(conn.params['hostname']), "INFO", False)
    while attempt < 20:
        if not conn.is_connected:
            robot_logger("[{}] Disconnected".format(conn.params['hostname']), "INFO", False)
            attempt = 0
            break
        else:
            attempt += 1
            if attempt == 20:
                raise Exception("[{}] Connection could not close after fpga reconfig".format(conn.params['hostname']))
            time.sleep(10)
            continue
    robot_logger("[{}] Connecting...".format(conn.params['hostname']), "INFO", False)
    while attempt < 20:
        try:
            with time_limit(60):
                force_connect(conn)
            robot_logger("[{}] Connected".format(conn.params['hostname']), "INFO", False)
            break
        except Exception as e:
            robot_logger("Connection failed: {}".format(e), "INFO", False)
            pass
        finally:
            attempt += 1
            if attempt == 20:
                raise Exception("[{}] Could not setup connection after fpga reconfig".format(conn.params['hostname']))
            time.sleep(10)


def force_connect(conn):
    if not conn.is_connected:
        proxy = conn.params.get('proxy')
        if proxy is not None:
            force_connect(proxy)
        conn.connect()


@contextmanager
def time_limit(seconds):
    def signal_handler(signum, frame):
        raise Exception("Timed out!")

    signal.signal(signal.SIGALRM, signal_handler)
    signal.alarm(seconds)
    try:
        yield
    finally:
        signal.alarm(0)


def perform_uboot_downgrade(test_phase, remote=False):
    admin_connection = get_admin_connection(remote)
    try:
        run_kw("Start Collecting Syslog", test_phase="{}/uboot_downgrade".format(test_phase))
        run_kw("Get Blackbox File Before Test", test_phase="{}/uboot_downgrade".format(test_phase), remote=remote)
        if downgrade_uboot(remote):
            verify_gps_after_firmware_upgrade(test_phase="uboot")
            robot_logger("Performing BTS Site Reset after Firmware Downgrade", "info")
            admin.reset_site(timeout=600, connection=admin_connection)
        run_kw("Watch Alarms", remote=remote)
        check_bts_state(1200, "{}/uboot_downgrade".format(test_phase), remote, timeout_for_alarms=30)
        run_kw("Get Blackbox File After Test", test_phase="{}/uboot_downgrade".format(test_phase), remote=remote)
        run_kw("Collect Syslog")
    except (UbootDowngradeError, BtsStateCheckError, Exception):
        run_kw("Gather Snapshot", "{}/uboot_downgrade".format(test_phase))
        raise
    finally:
        run_kw("Stop Logging", remote)


def get_uboot_version(connection):
    prepare_firmware_output = connection.execute("/ffs/run/prepare-firmware.sh -v")
    for line in prepare_firmware_output.splitlines():
        if "Actual installed u-boot on flash version:" in line:
            return line.split(": ")[1].strip()


def get_bios_version(connection):
    if str(connection.execute("test -f /tmp/startup_HWAPI.log.xz; echo $?").rstrip()) == '0':
        cat_cmd = "xzcat /tmp/startup_HWAPI.log.xz"
    else:
        cat_cmd = "cat /tmp/startup_HWAPI.log"
    current_bios_version = connection.execute("{} | grep 'running bios version' | awk '{{print $9}}'".
                                        format(cat_cmd)).replace(",", "").rstrip()
    return current_bios_version


def get_firmware_version(test_phase):
    firmware_version = {}
    check_module_type = r"""sysinfo 2>&1| head -n10 | grep "ID_00_MODULE_ID_\[0\]" | awk -F "'" '{print $2}'"""
    connection_list = setup_connections()
    bb_dict = get_bbmod_ips(connection_list)
    for sm_id, sm_conn in enumerate(reversed(connection_list)):
        try:
            sm_conn.files.put(prepare_firmware, "/ffs/run/prepare-firmware.sh")
            sm_conn.execute("chmod +x /ffs/run/prepare-firmware.sh")
        except Exception as e:
            robot_logger("Copying prepare-firmware.sh failed due to: {}".format(e), "ERROR")
            return
        finally:
            sm_conn.files.close()
        for bb_id, bb_ip in enumerate(reversed(bb_dict[sm_conn])):
            try:
                bb_conn = ssh.connect(hostname=bb_ip,
                                      username="toor4nsn",
                                      password="oZPS0POrRieRtu",
                                      proxy=sm_conn)
                bb_type = bb_conn.execute(check_module_type).rstrip()
                if bb_type in UBOOT_MODULE_LIST:
                    firmware_version["{}-{}".format(bb_type, bb_id)] = get_uboot_version(bb_conn)
                elif bb_type in BIOS_MODULE_LIST:
                    firmware_version["{}-{}".format(bb_type, bb_id)] = get_bios_version(bb_conn)
            finally:
                bb_conn.disconnect()
        sm_type = sm_conn.execute(check_module_type).rstrip()
        try:
            if sm_type in UBOOT_MODULE_LIST:
                firmware_version["{}-{}".format(sm_type, sm_id)] = get_uboot_version(sm_conn)
            elif sm_type in BIOS_MODULE_LIST:
                firmware_version["{}-{}".format(sm_type, sm_id)] = get_bios_version(sm_conn)
        finally:
            sm_conn.disconnect()

    set_robot_test_variable("FIRMWARE_{}".format(test_phase.upper()), deepcopy(firmware_version))
